INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_ADJECTIVE','Threshold');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_ATTACKED_1','The walls have doors. You should have remembered that.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_AVAILABLE','Available');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_BUILDING','Threshold House');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_BUILDING_HELP','Replaces Market. Inherits all active Community Patch Market properties and adds exactly +1 Culture. Enables this owned city as a Threshold Transfer endpoint; does not grant a free crossing or any further passive yield.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_BUILDING_PEDIA','A commercial hall of dark polished wood and restrained gothic arches. Behind the ledgers waits an ornate brass doorway, watched by the Hingeguard. Its merchants trade as other merchants do. The doorway changes the scale of the kingdom.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_BUILDING_STRATEGY','Build at both ends of a planned military corridor. Keep an empty military slot at the destination. Only a successful departure starts this city''s eight-turn cooldown; receiving a unit does not.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_BUSY','A Threshold Transfer is already being processed.');
