INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CIV','The Threshold Court');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CIV5_HEADING_1','Every Door Leads Somewhere');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CIV5_TEXT_1','An ancient kingdom is joined by doors concealed within its most important buildings. Mountains and oceans divide its maps, but not its corridors. Behind the merchants and counters of each Threshold House stands a polished wooden door edged in brass. A soldier can step through and emerge on another continent. The crossings demand money, preparation and eight turns of quiet at the door that sent them.[NEWLINE][NEWLINE]Every door leads somewhere. The Court has learned to ask where before opening it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CIV_PEDIA','An ancient kingdom is joined by doors concealed within its most important buildings. Mountains and oceans divide its maps, but not its corridors. Behind the merchants and counters of each Threshold House stands a polished wooden door edged in brass. A soldier can step through and emerge on another continent. The crossings demand money, preparation and eight turns of quiet at the door that sent them.[NEWLINE][NEWLINE]Every door leads somewhere. The Court has learned to ask where before opening it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CONFIRM','Confirm Transfer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_CONFIRM_TO','Confirm Transfer to {1_Name}');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_COOLDOWN','Origin portal recharging: {1_Num} turns remaining.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_DAWN','Queen Elsewhere, Sovereign of the Thresholds, the doors of destiny await your command.[NEWLINE][NEWLINE]For countless generations, humanity has been divided by mountains, oceans and the vast distances between nations.[NEWLINE][NEWLINE]Armies marched for years. Merchants crossed dangerous wildernesses. Families were separated by lands they could never hope to traverse.[NEWLINE][NEWLINE]But your ancestors discovered a secret.[NEWLINE][NEWLINE]The world is not as large as it appears.[NEWLINE][NEWLINE]Behind every wall lies another passage. Beyond every locked door waits another destination.[NEWLINE][NEWLINE]Now, your people have inherited the ancient Thresholds.[NEWLINE][NEWLINE]Establish your cities. Awaken the forgotten doorways. Let your soldiers travel where no army could ever march.[NEWLINE][NEWLINE]Will you build an empire spanning the world, or discover what waits beyond the final door?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_DEFEAT_1','So... this is where the last door leads.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_DEFENDER','Keeper of the Threshold');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_DEFENDER_HELP','+15% Combat Strength attacking or defending on friendly territory. Retained on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_ENGINE_REJECT','Native terrain or stacking rules reject this destination.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_EXHAUSTED','Threshold Exhaustion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_EXHAUSTED_HELP','Cannot move or make offensive attacks until the next owner-turn. Defends normally. Upgrades are deferred until recovery.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_EXHAUSTION','This unit is exhausted from a Threshold Transfer.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_FAILED','Relocation failed. No Gold or portal use consumed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_FRIENDLY_1','A door is always open to you.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_GOLD','Requires {1_Num} Gold.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_GREETING_1','Welcome. I trust your journey was pleasant. Mine took approximately three seconds.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_HEADER','Selected Unit: {1_Name}[NEWLINE]Origin: {2_Name}[NEWLINE]Cost: {3_Num} [ICON_GOLD]');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_HOSTILE_1','Some doors are better left closed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_INELIGIBLE','Requires an unembarked land melee military unit with offensive capability.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_INVALID_DEST','Destination is no longer a valid owned city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_INVALID_UNIT','Selected unit is no longer valid.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_LEADER','Queen Elsewhere');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_LEADER_PEDIA','Queen Elsewhere rules an ancient kingdom whose important buildings conceal doors connected to distant locations. Her throne room contains thirteen doors. Twelve lead to different parts of her kingdom. The thirteenth has never been opened. She speaks of journeys as other rulers speak of footsteps, yet keeps careful accounts of every crossing. The last door remains locked by royal command.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_NEUTRAL_1','Where would you like this conversation to lead?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_NOT_TURN','Available only during your active owner-turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_NO_DEST','No eligible destination. Build another Threshold House and leave its military slot open.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_NO_HOUSE','Missing Threshold House.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_NO_MOVES','The unit has no movement remaining or is busy.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_OCCUPIED','Military slot occupied.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_ORIGIN','Stand on an owned city tile containing a Threshold House.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_PEACE_1','Let us close this particular door.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_PERSISTENCE','Saved Threshold data is unavailable or corrupt. See Lua.log; transfer disabled.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_QUEEN_HEADING_1','The Closed Door');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_QUEEN_LIVED','An age beyond the threshold');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_QUEEN_NAME','Queen Elsewhere');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_QUEEN_SUBTITLE','Sovereign of the Thresholds');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_QUEEN_TEXT_1','Queen Elsewhere rules an ancient kingdom whose important buildings conceal doors connected to distant locations. Her throne room contains thirteen doors. Twelve lead to different parts of her kingdom. The thirteenth has never been opened. She speaks of journeys as other rulers speak of footsteps, yet keeps careful accounts of every crossing. The last door remains locked by royal command.');
