INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SPY_4','No Footsteps');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SPY_5','Brass Hand');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SPY_6','Elsewhere');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SPY_7','Night Hinge');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SPY_8','The Visitor');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SPY_9','Quiet Knock');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_STRATEGY','Construct a Threshold House network before committing to a distant war. Each origin can send a unit only once every eight owner-turns; only one transfer is allowed empire-wide each turn. Keep a destination garrison slot open and reserve Gold. Domination rewards strategic redeployment; Science benefits from a wide empire that can respond quickly to invasion.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_SUCCESS','{1_Unit} crossed from {2_Origin} to {3_Dest} for {4_Num} Gold. Origin ready on turn {5_Num}.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_TITLE','THRESHOLD TRANSFER');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_TRADE_1','Our ledgers agree.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_TRAIT','A Door in Every Wall');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_TRAIT_HELP','Once per owner-turn, teleport an unembarked land melee military unit from an owned Threshold House city to another owned Threshold House city with a free military slot. Unlimited distance. Costs 50 + 25 per current Era index Gold, charged only on success. The origin recharges at turn T+8. Arrivals cannot move or attack until the next owner-turn. Human-only.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_TRANSFER','Threshold Transfer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_UNIT','Hingeguard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_UNIT_HELP','Replaces Pikeman. Inherits the active Community Patch Pikeman, with +1 Movement and +15% Combat Strength when fighting on friendly territory. Retains the standard resources, promotions and upgrade path. Eligible for Threshold Transfer.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_UNIT_PEDIA','The Hingeguard wears heavy armor decorated with brass hinges and carries a shield resembling a reinforced wooden door. These soldiers know the kingdom by its thresholds rather than its roads. The field model and animations use the ordinary Pikeman.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_UNIT_STRATEGY','Guard your cities and prepare to reinforce distant Threshold Houses. Your extra movement aids positioning; the friendly-territory bonus helps reclaim your own ground and does not strengthen attacks in enemy territory.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_USED','Threshold Transfer already used this turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_THC_WAR_1','You have surrounded my city? How unfortunate. You seem to believe my army is somewhere else.');
